#include "fixtures/recovery/TestSupport.hpp"
#include <atomic>
#include <iostream>
#include <limits>
using namespace recovery_test;
namespace {
Array checks;int failed=0;fs::path evidence,run;
void check(const std::string& name,bool pass,const std::string& detail=""){checks.push_back(Object{{"case",name},{"passed",pass},{"detail",detail}});std::cout<<(pass?"PASS ":"FAIL ")<<name<<" "<<detail<<'\n';if(!pass)++failed;}
template<class F>void rejects(const std::string& name,F f,const std::string& code=""){try{f();check(name,false,"not rejected");}catch(const EnvelopeError& e){check(name,code.empty()||e.code==code,e.code);}catch(const std::exception& e){check(name,code.empty(),e.what());}}
void pure(){
 auto root=oracle(evidence,"");auto manifest=fathom::json::parse(read(root/"manifest.json"));
 for(const auto& c:at(manifest,"cases").array()){
  auto name=str(c,"name");auto dir=root/name;auto cp=load(dir/"checkpoint.json");RecoveryBinding b;b.owner=str(c,"owner");b.kind=str(c,"kind");b.context=load(dir/"context.json");b.currentGeneration=n(at(c,"current_generation"));b.currentSerial=n(at(c,"current_serial"));
  auto p=planRecovery(checkpointReply(cp),b);auto expected=read(dir/"expected-envelope.json");
  check(name+" exact expected original outcome",p.bytes==expected);check(name+" digest",p.digest==fathom::content::sha256(expected));check(name+" generation high-water",p.nextGeneration==n(at(c,"expected_generation")));check(name+" serial high-water",p.serial==n(at(c,"expected_serial")));check(name+" stopped",at(p.stoppedSnapshot,"state")==Value("STOPPED"));check(name+" exact active",at(at(validateEnvelope(p.bytes).value,"result"),"active")==at(at(cp,"practice_snapshot"),"active"));
  write(run/(name+"-plan.json"),canonical(Object{{"bytes",p.bytes},{"digest",p.digest},{"snapshot",p.stoppedSnapshot},{"generation",p.nextGeneration?num(*p.nextGeneration):Value(nullptr)},{"serial",num(p.serial)}}));
 }
 auto dir=root/"running-partial";auto cp=load(dir/"checkpoint.json");RecoveryBinding b;b.owner=str(cp,"owner");b.kind="Attempt";b.context=at(cp,"context");auto p=planRecovery(checkpointReply(cp),b);
 auto final=Reply{Status::Confirmed,"read",b.owner,"","",Object{{"state","final"},{"payload",p.bytes},{"digest",p.digest},{"stopped_on_reopen",true}}};check("final exact bytes wins",planRecovery(final,b).bytes==p.bytes);
 auto pending=final;at(pending.data,"state")="pending";check("pending original preserved",planRecovery(pending,b).kind==RecoveryKind::Original);
 auto bad=final;at(bad.data,"digest")="bad";rejects("bad durable digest",[&]{planRecovery(bad,b);},"RECOVERY_DIGEST");
 auto conflict=b;auto changed=parseCanonical(p.bytes);at(at(changed,"result"),"assessment")="Clean";conflict.originalSealedBytes=canonical(changed);rejects("final cannot hide sealed conflict",[&]{planRecovery(final,conflict);},"RECOVERY_CONFLICT");
 auto allocated=Reply{Status::Confirmed,"read",b.owner,"","",Object{{"state","allocated"},{"kind",b.kind},{"context",b.context},{"stopped_on_reopen",true}}};check("allocated only stopped unresolved",planRecovery(allocated,b).kind==RecoveryKind::NeedsInitialCheckpoint);
 b.currentGeneration=std::numeric_limits<std::int64_t>::max();rejects("generation overflow checked",[&]{planRecovery(checkpointReply(cp),b);},"RECOVERY_GENERATION");b.currentGeneration=0;
 auto exhausted=b;exhausted.currentGeneration=std::numeric_limits<std::int64_t>::max();check("final reconciliation at generation max",!planRecovery(final,exhausted).nextGeneration&&planRecovery(final,exhausted).bytes==p.bytes);check("pending reconciliation at generation max",planRecovery(pending,exhausted).bytes==p.bytes);auto sealedCp=load(root/"sealed-completed-timeout/checkpoint.json");auto sealedBinding=exhausted;sealedBinding.owner=str(sealedCp,"owner");sealedBinding.context=at(sealedCp,"context");check("sealed checkpoint reconciles at generation max",!planRecovery(checkpointReply(sealedCp),sealedBinding).nextGeneration);
 bad=checkpointReply(cp);bad.owner=newUuid();rejects("reply owner mismatch",[&]{planRecovery(bad,b);},"RECOVERY_REPLY");
 auto legacy=load(evidence/"reviewer/resource_plan_inputs/recovery-fixtures-01/running-partial/checkpoint.json");auto old=b;old.owner=str(legacy,"owner");old.context=at(legacy,"context");rejects("legacy missing bound metadata refuses",[&]{planRecovery(checkpointReply(legacy),old);},"RECOVERY_METADATA_REQUIRED");old.originalAuthoredTempoRef="bindings.json:source passages";check("legacy explicit original fixture metadata",planRecovery(checkpointReply(legacy),old).bytes==read(evidence/"reviewer/resource_plan_inputs/recovery-fixtures-01/running-partial/expected-envelope.json"));
 b.originalAuthoredTempoRef="different";rejects("pinned original metadata conflict",[&]{planRecovery(checkpointReply(cp),b);},"RECOVERY_BINDING");b.originalAuthoredTempoRef.reset();
 auto stringActive=cp;at(at(stringActive,"practice_snapshot"),"active")=Array{Value("5"),Value("2")};auto stringPlan=planRecovery(checkpointReply(stringActive),b);check("accepted string active representation preserved",at(at(parseCanonical(stringPlan.bytes),"result"),"active")==Array{Value("5"),Value("2")});
 auto stringSegment=cp;auto& stringSeg=at(at(stringSegment,"practice_snapshot"),"segment");for(auto key:{"tempo","start_at","end_at","confirmed_duration"}){auto& pair=at(stringSeg,key);for(auto& v:pair.array())v=std::to_string(n(v));}check("accepted string tempo segment representation preserved",at(at(parseCanonical(planRecovery(checkpointReply(stringSegment),b).bytes),"result"),"tempo_segments").array().back()==stringSeg);
 auto negativeZero=cp;at(at(at(negativeZero,"practice_snapshot"),"segment"),"start_at")=Array{Value(fathom::json::Number{"-0"}),num(1)};rejects("negative zero live ledger component refuses",[&]{planRecovery(checkpointReply(negativeZero),b);},"RECOVERY_INTEGER");
 auto malformed=cp;at(at(malformed,"practice_snapshot"),"segment")="not a confirmed tempo segment";rejects("malformed live segment refuses",[&]{planRecovery(checkpointReply(malformed),b);},"RECOVERY_LEDGER");
 auto badDuration=cp;at(at(at(badDuration,"practice_snapshot"),"segment"),"confirmed_duration")=Array{num(0),num(1)};rejects("segment duration mismatch refuses",[&]{planRecovery(checkpointReply(badDuration),b);},"RECOVERY_LEDGER");
 auto badTraversal=cp;at(at(at(badTraversal,"practice_snapshot"),"traversal"),"status")="complete";rejects("live traversal cannot be complete",[&]{planRecovery(checkpointReply(badTraversal),b);},"RECOVERY_LEDGER");
 auto badClosed=cp;at(at(badClosed,"practice_snapshot"),"segments")=Array{Value("bad")};rejects("malformed closed ledger refuses",[&]{planRecovery(checkpointReply(badClosed),b);},"RECOVERY_LEDGER");
 auto corrupt=cp;at(at(corrupt,"practice_snapshot"),"active")=Array{num(999),num(1)};rejects("corrupt active ledger refuses",[&]{planRecovery(checkpointReply(corrupt),b);});
}
void stored(){
 for(const auto& name:{"running-partial","sealed-completed-timeout","count-in-no-credit","freeplay-partial"}){
  auto dir=oracle(evidence,name);ProfileStore s(options(run/(std::string("stored-")+name)/"profile.sqlite"));auto cp=load(dir/"checkpoint.json");auto kind=std::string(name)=="freeplay-partial"?"FreeplayActivity":"Attempt";auto b=allocate(s,at(cp,"context"),kind);cp=rebindCheckpoint(cp,b.owner,b.context);auto snapshot=snap(cp);required(s.checkpoint("original-cp",b.owner,snapshot.generation,snapshot.sequence,snapshot.bytes));
  auto expected=canonical(rebindEnvelope(load(dir/"expected-envelope.json"),b.owner,b.context));RecoveryOperation op(s,b,"recover-original");await(op);check(std::string(name)+" committed original recovered",op.confirmed());check(std::string(name)+" exact original reconstructed",op.plan()&&op.plan()->bytes==expected);
  RecoveryOperation again(s,b,"recover-again");await(again);check(std::string(name)+" repeated recovery same receipt",again.confirmed()&&again.reply().data==op.reply().data);auto state=required(s.recoveryState("actual-final",b.owner));check(std::string(name)+" single durable original final",str(state.data,"payload")==expected&&n(at(state.data,"committed_seq"))==1);write(run/(std::string(name)+"-actual-final.json"),canonical(state.data));
 }
 ProfileStore s(options(run/"allocated-only"/"profile.sqlite"));auto b=allocate(s,load(oracle(evidence,"running-partial")/"context.json"),"Attempt");RecoveryOperation op(s,b,"only-allocation");await(op);check("allocated-only operation no success",!op.confirmed()&&op.reply().code=="INITIAL_CHECKPOINT_REQUIRED");auto r=s.allocate("again-before-recovery","Attempt",b.context,"2026-09-07T00:31:00Z").get();check("unresolved allocation cannot rekey",r.status!=Status::Confirmed);
}
void coordinator(){
 auto dir=oracle(evidence,"running-partial");auto cp=load(dir/"checkpoint.json");ProfileStore s(options(run/"coordinator"/"profile.sqlite"));auto b=allocate(s,at(cp,"context"),"Attempt");cp=rebindCheckpoint(cp,b.owner,b.context);auto first=cp;at(first,"sequence")=num(0);at(at(first,"practice_snapshot"),"generation")=num(0);
 CheckpointCoordinator c(s,b.owner,b.kind,b.context,"cp");check("initial gate closed at timestamp zero",c.state(0).stopRequired);c.offer(snap(first),0);check("initial exact future retained",c.state(0).inFlightSnapshot->bytes==canonical(first));gate(c);check("initial acknowledged gate opens",!c.state(0).stopRequired&&c.state(0).initialAcknowledged);
 auto next=first;at(next,"sequence")=num(1);c.offer(snap(next),100);check("cadence retains deferred bytes",!c.state(100).inFlight&&c.state(100).unsaved->bytes==canonical(next));c.poll(999);check("no premature cadence write",!c.state(999).inFlight);c.poll(1000);gate(c,1000);check("cadence exact acknowledged",c.state(1000).acknowledged->bytes==canonical(next));
 auto forced=next;at(forced,"sequence")=num(2);c.offer(snap(forced),1001,true);gate(c,1001);check("force bypasses cadence",c.state(1001).acknowledged->sequence==2);check("paused unchanged facts no wall credit or unhealthy age",!c.state(5000).stopRequired);
 rejects("clock regression refuses",[&]{c.poll(4999);},"CHECKPOINT_CLOCK");rejects("stale sequence refuses",[&]{c.offer(snap(first),5000);},"CHECKPOINT_STALE");auto wrong=forced;at(at(wrong,"practice_snapshot"),"uncertain")=true;rejects("same position bytes conflict",[&]{c.offer(snap(wrong),5000);},"CHECKPOINT_CONFLICT");
 auto newgen=forced;at(newgen,"sequence")=num(0);at(at(newgen,"practice_snapshot"),"generation")=num(1);c.offer(snap(newgen),5000,true);gate(c,5000);check("new generation may reset sequence",c.state(5000).acknowledged->generation==1&&c.state(5000).acknowledged->sequence==0);
}
void delayed(){
 std::atomic<bool> release{false},entered{false};auto o=options(run/"delayed"/"profile.sqlite");o.diagnosticHook=[&](const std::string& phase,const std::string& op){if(phase=="before_commit"&&op=="cp.1.2"){entered=true;while(!release.load())std::this_thread::sleep_for(std::chrono::milliseconds(1));}};
 ProfileStore s(o);auto cp=load(oracle(evidence,"running-partial")/"checkpoint.json");auto b=allocate(s,at(cp,"context"),"Attempt");cp=rebindCheckpoint(cp,b.owner,b.context);CheckpointCoordinator c(s,b.owner,b.kind,b.context,"cp");c.offer(snap(cp),0);
 for(int i=0;i<1000&&!entered;++i)std::this_thread::sleep_for(std::chrono::milliseconds(1));check("delayed original reached hook",entered);
 auto later=cp;at(later,"sequence")=num(3);c.offer(snap(later),100,true);c.poll(1000);auto st=c.state(1000);check("timeout preserves original future and exact deferred",st.inFlight&&st.stopRequired&&st.code=="CHECKPOINT_ACK_TIMEOUT"&&st.inFlightSnapshot->sequence==2&&st.unsaved->sequence==3);
 release=true;gate(c,1001);check("late acknowledgment leaves stop latched",c.state(1001).stopRequired);check("explicit stopped resolution after exact ACKs",c.resolveAcknowledgedWhileStopped()&&!c.state(1001).stopRequired);check("late acknowledgment cannot relabel newer payload",c.state(1001).acknowledged->sequence==3);auto state=required(s.recoveryState("inspect",b.owner));check("deferred forced snapshot eventually exact",str(state.data,"payload")==canonical(later));
}
void failedWrite(){
 auto o=options(run/"failed-write"/"profile.sqlite");o.diagnosticHook=[](const std::string& phase,const std::string& op){if(phase=="before_commit"&&op=="fail.1.2")throw std::runtime_error("controlled rollback-before-checkpoint-commit");};ProfileStore s(o);auto cp=load(oracle(evidence,"running-partial")/"checkpoint.json");auto b=allocate(s,at(cp,"context"),"Attempt");cp=rebindCheckpoint(cp,b.owner,b.context);CheckpointCoordinator c(s,b.owner,b.kind,b.context,"fail");c.offer(snap(cp),0);gate(c);auto st=c.state(1001);check("failed write cannot claim saved",!st.initialAcknowledged&&st.stopRequired&&st.hasUnsaved&&st.code=="CHECKPOINT_WRITE_UNRESOLVED"&&st.inFlightSnapshot->bytes==canonical(cp));check("failed future does not retry itself",!st.inFlight);auto r=required(s.recoveryState("actual-unsaved",b.owner));check("failed checkpoint absent allocated retained",str(r.data,"state")=="allocated");
}
}
int main(int argc,char** argv){if(argc!=3)return 64;try{evidence=fs::canonical(argv[1]);run=evidence/"test-data"/argv[2];boundedPath(evidence,run);if(fs::exists(run))throw std::runtime_error("New run directory required");fs::create_directories(run);pure();stored();coordinator();delayed();failedWrite();write(run/"checks.json",canonical(Object{{"checks",checks},{"passed",num(static_cast<std::int64_t>(checks.size())-failed)},{"failed",num(failed)},{"classification","synthetic practice / actual local SQLite and async worker"}}));return failed?1:0;}catch(const std::exception& e){std::cerr<<"FATAL "<<e.what()<<'\n';if(!run.empty()&&fs::exists(run))write(run/"fatal.json",canonical(Object{{"error",e.what()},{"checks",checks}}));return 2;}}
